package ru.screenrecorder.app;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import java.net.*;import java.io.*;import java.security.*;import java.time.Instant;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import org.json.*;
final class Updater {
 static final String REPO="https://api.github.com/repos/nicolenkoe/screen-recorder-downloads/releases";
 static final AtomicBoolean busy=new AtomicBoolean();static volatile boolean again;static final Handler main=new Handler(Looper.getMainLooper());
 static void check(MainActivity a,boolean explicit){if(!busy.compareAndSet(false,true)){again=true;return;}new Thread(()->{String message=null;File ready=null;try{
  boolean stable=a.prefs.getBoolean("stable",false);List<ReleasePolicy.Release> candidates=new ArrayList<>();HashMap<String,JSONObject> metadata=new HashMap<>();boolean anyStable=false;
  for(int page=1;;page++){JSONArray releases=new JSONArray(new String(read(REPO+"?per_page=100&page="+page,4000000),"UTF-8"));for(int n=0;n<releases.length();n++){JSONObject r=releases.getJSONObject(n);if(r.optBoolean("draft"))continue;boolean isStable=!r.optBoolean("prerelease");if(stable&&!isStable)continue;JSONArray assets=r.getJSONArray("assets");String manifest=null;for(int k=0;k<assets.length();k++){JSONObject asset=assets.getJSONObject(k);if("update.json".equals(asset.optString("name")))manifest=asset.getString("browser_download_url");}if(manifest==null)continue;JSONObject m=new JSONObject(new String(read(manifest,100000),"UTF-8"));if(!a.getPackageName().equals(m.getString("packageName")))continue;if(isStable)anyStable=true;String abi=m.optString("abi","universal");if(!"universal".equals(abi)&&!Arrays.asList(Build.SUPPORTED_ABIS).contains(abi))continue;long published=Instant.parse(r.getString("published_at")).toEpochMilli();String name=r.getString("tag_name");ReleasePolicy.Release p=new ReleasePolicy.Release(name,published,m.getLong("versionCode"),m.getInt("minSdk"),m.optInt("maxSdk",0),isStable);candidates.add(p);metadata.put(name,m);}
   if(releases.length()<100)break;
  }
  ReleasePolicy.Release best=ReleasePolicy.choose(candidates,stable,Build.VERSION.SDK_INT);if(best==null){message=stable&&!anyStable?"Стабильные сборки пока не опубликованы.":"Совместимых опубликованных сборок пока нет.";}else{
   long installed=a.getPackageManager().getPackageInfo(a.getPackageName(),0).getLongVersionCode();JSONObject m=metadata.get(best.name);if(best.version<=installed){message=stable&&best.version<installed?"Последняя стабильная сборка старее установленной. Android не устанавливает её поверх более новой версии.":"Установлена актуальная версия.";}else{
    String hash=m.getString("sha256").toLowerCase(Locale.ROOT);if(!hash.matches("[0-9a-f]{64}"))throw new IOException("Неверный SHA-256 в описании сборки");long size=m.getLong("size");if(size<=0||size>500000000)throw new IOException("Некорректный размер APK");File dir=new File(a.getFilesDir(),"updates");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Нет папки обновлений");File apk=new File(dir,best.version+"-"+hash+".apk");
    if(!valid(a,apk,m)){File part=new File(dir,apk.getName()+".part");try{download(m.getString("url"),part,size,a,stable);if(!valid(a,part,m))throw new IOException("APK не прошёл проверку размера, SHA-256, пакета, версии или подписи");if(apk.exists()&&!apk.delete())throw new IOException("Не удалось заменить повреждённый APK");if(!part.renameTo(apk))throw new IOException("Не удалось сохранить APK");}finally{part.delete();}}
    if(a.prefs.getBoolean("stable",false)!=stable){again=true;throw new IOException("Настройки изменились");}ready=apk;message="Обновление скачано и проверено.";
   }
  }
 }catch(Exception e){message="Обновление: "+e.getMessage();}finally{busy.set(false);}final File apk=ready;final String text=message;main.post(()->{if(!a.isFinishing()&&a.resumed){if(apk!=null&&RecordingService.active==null&&System.currentTimeMillis()>=a.prefs.getLong("later",0))new AlertDialog.Builder(a).setTitle("Обновление готово").setMessage("APK проверен. Установку подтвердит Android.").setPositiveButton("Установить",(d,w)->install(a,apk)).setNegativeButton("Позже",(d,w)->a.prefs.edit().putLong("later",System.currentTimeMillis()+30*60*1000).apply()).show();else if(explicit)a.message(text);}if(again){again=false;if(a.resumed)check(a,false);}});
 },"update-check").start();}
 static HttpURLConnection connection(String address)throws Exception{URL url=new URL(address);if(!"https".equals(url.getProtocol()))throw new IOException("Обновления разрешены только по HTTPS");String h=url.getHost();if(!h.equals("api.github.com")&&!h.equals("github.com")&&!h.endsWith(".githubusercontent.com"))throw new IOException("Неизвестный сервер обновлений");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","ScreenRecorder-Android");c.setUseCaches(false);if(c.getResponseCode()!=200){int code=c.getResponseCode();c.disconnect();throw new IOException("Сервер вернул "+code);}return c;}
 static byte[] read(String address,int limit)throws Exception{HttpURLConnection c=connection(address);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];for(int n;(n=in.read(b))!=-1;){if(out.size()+n>limit)throw new IOException("Слишком большой ответ сервера");out.write(b,0,n);}return out.toByteArray();}finally{c.disconnect();}}
 static void download(String address,File target,long size,MainActivity a,boolean stable)throws Exception{HttpURLConnection c=connection(address);try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(target)){byte[] b=new byte[65536];long total=0;for(int n;(n=in.read(b))!=-1;){if(a.prefs.getBoolean("stable",false)!=stable){again=true;throw new IOException("Настройки обновлений изменились; повторяем проверку");}total+=n;if(total>size)throw new IOException("Размер загрузки превышен");out.write(b,0,n);}out.getFD().sync();if(total!=size)throw new IOException("APK скачан не полностью");}finally{c.disconnect();}}
 static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static boolean valid(Context context,File f,JSONObject m){try{if(!f.isFile()||f.length()!=m.getLong("size"))return false;MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)md.update(b,0,n);}if(!hex(md.digest()).equalsIgnoreCase(m.getString("sha256")))return false;PackageManager pm=context.getPackageManager();PackageInfo archive=pm.getPackageArchiveInfo(f.getAbsolutePath(),PackageManager.GET_SIGNING_CERTIFICATES),current=pm.getPackageInfo(context.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);if(archive==null||!current.packageName.equals(archive.packageName)||archive.getLongVersionCode()!=m.getLong("versionCode")||archive.signingInfo==null)return false;Set<String>a=certificates(archive),b=certificates(current);return !a.isEmpty()&&a.equals(b);}catch(Exception e){return false;}}
 static Set<String> certificates(PackageInfo p)throws Exception{Set<String> hashes=new HashSet<>();for(android.content.pm.Signature s:p.signingInfo.getApkContentsSigners())hashes.add(hex(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));return hashes;}
 static void install(MainActivity a,File apk){if(!a.getPackageManager().canRequestPackageInstalls()){a.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));return;}Uri u=Uri.parse("content://"+a.getPackageName()+".updates/"+apk.getName());a.startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(u,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}
}
